1	export type Cell = [number, number];
2	
3	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighbors = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	const isAliveNextGeneration = (isAlive: boolean, liveNeighbors: number): boolean =>
17	  isAlive ? liveNeighbors === 2 || liveNeighbors === 3 : liveNeighbors === 3;
18	
19	export const nextGeneration = (liveCells: Cell[]): Cell[] => {
20	  const livingKeys = new Set(liveCells.map(cellKey));
21	  const isAlive = (cell: Cell): boolean => livingKeys.has(cellKey(cell));
22	  const liveNeighborCount = (cell: Cell): number =>
23	    neighbors(cell).filter(isAlive).length;
24	
25	  const candidates = new Map(
26	    liveCells
27	      .flatMap((cell) => [cell, ...neighbors(cell)])
28	      .map((cell) => [cellKey(cell), cell] as const),
29	  );
30	
31	  return [...candidates.values()].filter((cell) =>
32	    isAliveNextGeneration(isAlive(cell), liveNeighborCount(cell)),
33	  );
34	};
